import itertools, json
Aopts = ['KMP','LNP','KLN','MQR','LMQ']
Bopts = ['LPQ','NPR','LMP','MNR','KNP']
Adays = [{2,7},{1,6,7},{7},{8},{2,7}]
Bdays = [{4,6},{3},{2,8},{3},{6,7,8}]
people = set('KLMNPQR')
west = set('KPR')
As = [x for x in itertools.product(*Aopts) if len(set(x)) == 5]
Bs = [x for x in itertools.product(*Bopts) if len(set(x)) == 5]
counts = {}
witnesses = {}
total = 0
for a in As:
    for b in Bs:
        overlap = set(a) & set(b)
        if len(overlap) != 3 or len(overlap & west) != 1:
            continue
        days = {p:set() for p in people}
        for p,d in zip(a,Adays): days[p].update(d)
        for p,d in zip(b,Bdays): days[p].update(d)
        n = sum(len(d)>=3 for d in days.values())
        total += 1
        counts[n] = counts.get(n,0)+1
        witnesses.setdefault(n, {'A': ''.join(a), 'B': ''.join(b)})
lo, hi = min(counts), max(counts)
result = {'feasible_linkages':total, 'bounds':[lo,hi], 'low_witness':witnesses[lo], 'high_witness':witnesses[hi], 'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
print(json.dumps(result))
print('distribution', counts)
for n in [lo,hi]:
    w=witnesses[n]
    days={p:set() for p in people}
    for p,d in zip(w['A'],Adays): days[p].update(d)
    for p,d in zip(w['B'],Bdays): days[p].update(d)
    print(n, {p:sorted(days[p]) for p in sorted(people)})

